package main

import (
	"bufio"
	"bytes"
	"fmt"
	"os"
	"sort"
)

type FastScanner struct {
	reader *bufio.Reader
	buf    []byte
}

func NewFastScanner() *FastScanner {
	return &FastScanner{
		reader: bufio.NewReaderSize(os.Stdin, 1024*10),
		buf:    make([]byte, 0, 1024),
	}
}

func (s *FastScanner) NextInt() int {
	c, err := s.reader.ReadByte()
	for err == nil && (c < '0' || c > '9') {
		c, err = s.reader.ReadByte()
	}
	if err != nil {
		return 0
	}
	res := int(c - '0')
	for {
		c, err = s.reader.ReadByte()
		if err != nil || c < '0' || c > '9' {
			return res
		}
		res = res*10 + int(c-'0')
	}
}

type Interval struct {
	l, r int
}

func Find(dp [][]Interval, value Interval, index int) bool {
	for i := index - 2; i >= 0; i -= 2 {
		arr := dp[i]
		if len(arr) == 0 {
			continue
		}
		// Binary search for first interval with l >= value.l
		ind := sort.Search(len(arr), func(j int) bool {
			return arr[j].l >= value.l
		})

		if ind < len(arr) && arr[ind].r >= value.r {
			return true
		}
		if ind > 0 && arr[ind-1].r >= value.r {
			return true
		}
	}
	return false
}

func main() {
	scanner := NewFastScanner()
	writer := bufio.NewWriterSize(os.Stdout, 1024*10)
	defer writer.Flush()

	n := scanner.NextInt()
	k := scanner.NextInt()

	l := make([]int, k)
	r := make([]int, k)
	for i := 0; i < k; i++ {
		l[i] = scanner.NextInt()
		r[i] = scanner.NextInt()
	}

	dpSize := 2*k + 1
	dp := make([][]Interval, dpSize)
	for i := 0; i < dpSize; i++ {
		dp[i] = make([]Interval, 0, 4)
	}
	dp[0] = append(dp[0], Interval{0, 0})

	prev := 0
	for i := 0; i < k; i++ {
		next := make([][]Interval, dpSize)
		for ii := 0; ii < dpSize; ii++ {
			next[ii] = make([]Interval, 0, 4)
		}

		delta := l[i] - prev
		for index := 0; index < dpSize; index++ {
			if index%2 == 0 {
				for j := range dp[index] {
					dp[index][j].l += delta
					dp[index][j].r += delta
				}
			}
		}

		delta = r[i] - l[i]
		for ii := 0; ii < dpSize; ii++ {
			if ii%2 == 0 {
				for _, interval := range dp[ii] {
					if ii < dpSize {
						next[ii] = append(next[ii], Interval{interval.l + delta, interval.r + delta})
					}
					if ii+1 < dpSize {
						next[ii+1] = append(next[ii+1], Interval{interval.l, interval.r + delta})
					}
					if ii+2 < dpSize {
						next[ii+2] = append(next[ii+2], Interval{interval.l, interval.r + delta})
					}
				}
			} else {
				for _, interval := range dp[ii] {
					if ii < dpSize {
						next[ii] = append(next[ii], Interval{interval.l, interval.r})
					}
					if ii+1 < dpSize {
						next[ii+1] = append(next[ii+1], Interval{interval.l, interval.r + delta})
					}
					if ii+2 < dpSize {
						next[ii+2] = append(next[ii+2], Interval{interval.l, interval.r + delta})
					}
				}
			}
		}

		prev = r[i]
		for index := 0; index < dpSize; index++ {
			dp[index] = dp[index][:0]

			sort.Slice(next[index], func(a, b int) bool {
				return next[index][a].l < next[index][b].l
			})

			var pr *Interval
			for _, interval := range next[index] {
				if interval.l > n {
					break
				}
				if pr != nil && pr.r >= interval.l {
					if interval.r > pr.r {
						pr.r = interval.r
					}
				} else {
					if pr != nil && !Find(dp, *pr, index) {
						dp[index] = append(dp[index], *pr)
					}
					pr = &interval
				}
			}
			if pr != nil && !Find(dp, *pr, index) {
				dp[index] = append(dp[index], *pr)
			}
		}
	}

	delta := 2*n - prev
	for index := 0; index < dpSize; index++ {
		if index%2 == 0 {
			for j := range dp[index] {
				dp[index][j].l += delta
				dp[index][j].r += delta
			}
		}
	}

	for i := 0; i < dpSize; i++ {
		for _, interval := range dp[i] {
			if interval.l <= n && interval.r >= n {
				writer.WriteString("Full\n")
				writer.WriteString(fmt.Sprintf("%d\n", i))
				return
			}
		}
	}

	writer.WriteString("Hungry\n")
}

